INSERT OR IGNORE INTO tactics (id, slug, map, side, team_size, economy, difficulty, spawn_dependent, content, game_version, source, author_id, status, featured, created_at, updated_at) VALUES
('demo-a-split', 'demo-a-split', 'dust2', 'T', 5, 'full', 2, 0, '{"title":"Сплит A: лонг + кат","call":"Трое лонг, двое кат, заход вместе по смоку на крест.","quick":["Трое забирают лонг, двое ждут в нижнем миде","Смок на CT и на крест, флешка над дверями лонга","Встал смок на крест — заходим с двух сторон разом"],"roles":[],"nades":[]}', 'unverified-demo', 'authors', 'demo-author', 'draft', 0, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
('demo-b-rush', 'demo-b-rush', 'dust2', 'T', 5, 'force', 1, 0, '{"title":"Раш Б через туннели","call":"Все в туннели, смоки в окно и на двери, влетаем толпой.","quick":["Все пятеро в верхний туннель","Смок в окно и на двери Б, две флешки над выходом","Влетаем толпой, бомбу на задний плент"],"roles":[],"nades":[]}', 'unverified-demo', 'authors', 'demo-author', 'draft', 0, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
('demo-duo-mid', 'demo-duo-mid', 'dust2', 'T', 2, 'any', 1, 0, '{"title":"Дуо: забираем мид","call":"Смок на иксбокс, один прыгает на кат и коллит инфу.","quick":["Первый с T-спавна кидает смок на иксбокс","Второй под смоком прыгает на кат","Даёте инфу по A — тима решает, куда идти"],"roles":[],"nades":[]}', 'unverified-demo', 'authors', 'demo-author', 'draft', 0, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
('demo-fake-a', 'demo-fake-a', 'dust2', 'T', 5, 'full', 3, 0, '{"title":"Фейк A → заход Б","call":"Двое шумят на лонге, трое тихо ждут ротацию и идут на Б.","quick":["Двое шумят на лонге и кидают гранаты на A","Трое тихо ждут в верхнем туннеле","КТ ротнулись на A — заходим на Б"],"roles":[],"nades":[]}', 'unverified-demo', 'authors', 'demo-author', 'draft', 0, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
('demo-ct-retake-b', 'demo-ct-retake-b', 'dust2', 'CT', 3, 'full', 2, 0, '{"title":"Ретейк Б втроём","call":"Смок на туннель, флешки через двери, заход с двух сторон.","quick":["Собираемся у дверей Б и в окне","Смок на выход из туннеля, флешки через двери","Заходим с дверей и окна одновременно"],"roles":[],"nades":[]}', 'unverified-demo', 'authors', 'demo-author', 'draft', 0, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z'),
('demo-ct-mid-aggro', 'demo-ct-mid-aggro', 'dust2', 'CT', 2, 'any', 2, 0, '{"title":"Агро мид на старте","call":"Ранний пик мида с дверей и откат, второй страхует с ката.","quick":["Первый пикает мид с мидовых дверей на старте","Второй страхует с ката","Есть фраг или нет — откат на позиции"],"roles":[],"nades":[]}', 'unverified-demo', 'authors', 'demo-author', 'draft', 0, '2026-10-19T00:00:00.000Z', '2026-10-19T00:00:00.000Z');

